#!/usr/bin/env bash
# Writes the AI guide files into the WORKSPACE folder that contains both
# repositories side by side:
#
#   <workspace>/rajat_crm_node_backend
#   <workspace>/rajat_crm_native_frontend
#
# The workspace folder is not a git repository, so these files are generated
# from the versioned copy in docs/shared/WORKSPACE_GUIDE.md. Re-run after
# changing that file, or on a new machine. Usage (from either repo):
#   scripts/setup-workspace-root.sh
#
# Files it writes in the workspace folder (only if absent or previously
# generated by this script — a file without the marker is left alone):
#   AGENTS.md, CLAUDE.md, GEMINI.md, .github/copilot-instructions.md,
#   .cursor/rules/crm-workspace.mdc, .windsurfrules, .clinerules
# If the workspace has the AG Kit toolkit (.agents/manifest.json), it also
# adds .agents/rules/crm-workspace.md and re-registers it with the kit's own
# generate_manifest.py, then runs its validator; on failure it rolls back.
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WS="$(dirname "$REPO")"
MARKER="Generated by rajat_crm scripts/setup-workspace-root.sh"
GUIDE="$REPO/docs/shared/WORKSPACE_GUIDE.md"

[ -f "$GUIDE" ] || { echo "Missing $GUIDE" >&2; exit 1; }
for r in rajat_crm_node_backend rajat_crm_native_frontend; do
  [ -d "$WS/$r/.git" ] || echo "WARNING: $WS/$r is missing — clone it next to this repo." >&2
done

# write_owned <path> <content>: create/overwrite only files we generated before
write_owned() {
  local path="$1" content="$2"
  if [ -f "$path" ] && ! grep -q "$MARKER" "$path"; then
    echo "SKIP  $path (exists and was not generated by this script)"
    return
  fi
  mkdir -p "$(dirname "$path")"
  printf '%s\n' "$content" > "$path"
  echo "WROTE $path"
}

POINTER="# Instructions for AI assistants — CRM workspace

<!-- $MARKER -->

This folder is a WORKSPACE holding two separate git repositories of one
project (Rajat Electricals CRM):

1. \`rajat_crm_native_frontend/\` — the app (Expo / React Native: Android, iOS, web)
2. \`rajat_crm_node_backend/\` — the REST API (Node.js / Express / Prisma / PostgreSQL)

Before doing anything, read \`AGENTS.md\` in this folder completely, then the
\`AGENTS.md\` of each repository you will change. Everything written into the
repositories must be in English. After any change, follow
\`docs/shared/DOCUMENTATION_PROTOCOL.md\` (inside either repository)."

write_owned "$WS/AGENTS.md" "$(cat "$GUIDE")

<!-- $MARKER from docs/shared/WORKSPACE_GUIDE.md — edit that file, then re-run the script. -->"
write_owned "$WS/CLAUDE.md" "# CLAUDE.md

<!-- $MARKER -->

This is the workspace folder for two repositories (see AGENTS.md, imported
below). Read it before doing anything.

@AGENTS.md"
write_owned "$WS/GEMINI.md" "$POINTER"
write_owned "$WS/.github/copilot-instructions.md" "$POINTER"
write_owned "$WS/.windsurfrules" "$POINTER"
write_owned "$WS/.clinerules" "$POINTER"
write_owned "$WS/.cursor/rules/crm-workspace.mdc" "---
description: CRM workspace — two repositories; read AGENTS.md first
alwaysApply: true
---

$POINTER"

# Google Antigravity + AG Kit: rules are discovered from .agents/rules and
# must be registered in the kit's manifest.
KIT="$WS/.agents"
if [ -f "$KIT/manifest.json" ] && [ -f "$KIT/scripts/generate_manifest.py" ]; then
  RULE="$KIT/rules/crm-workspace.md"
  BACKUP="$(mktemp -d)"
  cp "$KIT/manifest.json" "$KIT/manifest.lock.json" "$BACKUP/" 2>/dev/null || true
  write_owned "$RULE" "---
name: crm-workspace
version: 1.0.0
priority: P0
trigger: always_on
---

$POINTER"
  if python3 "$KIT/scripts/generate_manifest.py" "$KIT" >/dev/null \
     && python3 "$KIT/scripts/validate_kit.py" >/dev/null 2>&1; then
    echo "AG Kit: rule crm-workspace registered and toolkit validated."
  else
    echo "AG Kit validation failed — rolling back the AG Kit rule." >&2
    rm -f "$RULE"
    cp "$BACKUP/manifest.json" "$BACKUP/manifest.lock.json" "$KIT/" 2>/dev/null || true
  fi
  rm -rf "$BACKUP"
fi

echo "Done. Workspace guide: $WS/AGENTS.md"
